-- mvtk/tiled/spawners/interaction.lua
-- Generated by splitting mvtk.tiled.object_spawner handlers by domain.

local OP = require "mvtk.tiled.object_props"

return function(H)
    local handlers = {}

    local M = H.M
    local Util = H.Util
    local TriggerPayloads = H.TriggerPayloads
    local CollectibleManager = H.CollectibleManager
    local EnemyManager = H.EnemyManager
    local TileSnap = H.TileSnap
    local get_gate_manager = H.get_gate_manager
    local get_boss_arena = H.get_boss_arena
    local get_tile_settings = H.get_tile_settings
    local get_room_world_offset = H.get_room_world_offset
    local to_bool = H.to_bool
    local resolve_rect_size_pixels = H.resolve_rect_size_pixels
    local rect_scale_from_size = H.rect_scale_from_size
    local resolve_breakable_swap_extent = H.resolve_breakable_swap_extent
    local parse_color_string = H.parse_color_string
    local non_empty_string = H.non_empty_string
    local resolve_boss_preset = H.resolve_boss_preset
    local resolve_boss_display_name = H.resolve_boss_display_name
    local get_props = H.get_props
    local make_id = H.make_id
    local world_point = H.world_point
    local world_rect = H.world_rect
    local spawn_factory = H.spawn_factory
    local spawn_collection = H.spawn_collection
    local post_collectible_tiled_overrides = H.post_collectible_tiled_overrides
    local apply_scale = H.apply_scale
    local make_scale = H.make_scale
    local send_tiled_props = H.send_tiled_props
    local log_spawn = H.log_spawn
    local log_register = H.log_register
    local get_type_prop = H.get_type_prop
    local record_error = H.record_error
    local normalize_gate_type_name = H.normalize_gate_type_name
    local normalize_gate_item_name = H.normalize_gate_item_name
    local parse_drops_string = H.parse_drops_string
    local resolve_chest_loot_table = H.resolve_chest_loot_table
    local resolve_difficulty_scaling = H.resolve_difficulty_scaling
    local print = H.print
    local polyline_registry = H.polyline_registry

    local function optional_id(value)
        local id = non_empty_string(value)
        return id == "none" and nil or id
    end

function handlers.save_point(object, room_id)
    local props = get_props(object)
    local save_id = make_id(props, "save_id", "save", object, room_id)
    local world_x, world_y, pos = world_point(object, room_id)

    msg.post("main:/main_go#script", hash("register_save_point"), {
        id = save_id,
        position = pos,
        room_id = room_id,
        name = props.display_name or object.name or "Save Point",
        heal_on_save = to_bool(props.heal_on_save, true),
        restore_energy = to_bool(props.restore_energy, true),
        is_fast_travel = to_bool(props.is_fast_travel, false),
        show_on_map = to_bool(props.show_on_map, true),
        requires_interact = to_bool(props.requires_interact, true),
        sound_id = optional_id(props.sound_id) or "",
        particle_id = optional_id(props.particle_id) or "",
        properties = props,
    })

    log_register("save point", save_id, world_x, world_y)
    return save_id
end

--- Handle spawn point object (player spawn, respawn point)
-- Tiled properties:
--   spawn_type: string ("player", "checkpoint", "respawn")
--   facing: int (player facing direction on spawn)
--   is_default: bool (mark as default spawn point)
--   checkpoint_id: string (link to checkpoint system)

function handlers.spawn_point(object, room_id)
    local props = get_props(object)
    local spawn_type = props.spawn_type or "player"
    local world_x, world_y, pos = world_point(object, room_id)
    local spawn_id = OP.get(props, "spawn_id") or props.id or object.id
    local is_default = props.is_default
    if is_default == nil then
        is_default = props.default
    end

    msg.post("main:/main_go#script", hash("register_spawn_point"), {
        id = spawn_id,
        position = pos,
        room_id = room_id,
        spawn_type = spawn_type,
        name = object.name or "Spawn Point",
        facing = props.facing or 1,
        is_default = to_bool(is_default, false),
        checkpoint_id = props.checkpoint_id or "",
        properties = props,
    })

    log_register("spawn point", spawn_type, world_x, world_y)
    return spawn_id
end

--- Handle ability pickup object

function handlers.cutscene(object, room_id)
    local props = get_props(object)
    local cutscene_id = Util.trim(props.cutscene_id or "")
    if cutscene_id == "" then
        cutscene_id = Util.trim(props.cutscene_name or "")
    end
    if cutscene_id == "" then
        cutscene_id = Util.trim(object.name or "")
    end
    if cutscene_id == "" then
        cutscene_id = string.format("cutscene_%s_%d", tostring(room_id), tonumber(object.id) or 0)
    end
    local trigger_id = Util.trim(props.trigger_id or "")
    if trigger_id == "" then
        trigger_id = Util.trim(props.cutscene_name or "")
    end
    if trigger_id == "" then
        trigger_id = Util.trim(object.name or "")
    end
    if trigger_id == "" then
        trigger_id = tostring(object.id)
    end
    local register_id = string.format("%s_cutscene_%s", tostring(room_id), tostring(object.id))
    local _, _, pos = world_point(object, room_id)

    msg.post("main:/main_go#script", hash("register_cutscene_trigger"), TriggerPayloads.cutscene({
        id = register_id,
        position = pos,
        width = object.width,
        height = object.height,
        room_id = room_id,
        trigger_id = trigger_id,
        cutscene_id = cutscene_id,
        cutscene_name = props.cutscene_name or "",
        auto_play = props.auto_play,
        trigger_once = props.trigger_once,
        consume_on_fire = props.consume_on_fire,
        persist_once = props.persist_once,
        requires_flag = props.requires_flag,
        skip_if_flag = props.skip_if_flag,
        set_flag = props.set_flag,
        once_flag = props.once_flag,
        video_id = props.video_id or "",
        video_uri = props.video_uri or "",
        video_play_sound = props.video_play_sound,
        video_timeout = props.video_timeout,
        cutscene_dialogue_id = props.cutscene_dialogue_id or "",
        cutscene_use_fade = props.cutscene_use_fade,
        cutscene_wait = props.cutscene_wait,
        properties = props,
    }))

    log_register("cutscene trigger", cutscene_id, pos.x, pos.y)
    return object.id
end

--- Handle NPC object
-- Tiled properties:
--   npc_type: string (NPC type from npc_types.lua, e.g. "guide", "villager_male")
--   npc_name: string (Display name override)
--   dialogue_id: string (Dialogue to play when interacted)

function handlers.npc(object, room_id)
    local props = get_props(object)
    local npc_id = non_empty_string(props.npc_id) or string.format("%s_npc_%d", Util.room_key(room_id), tonumber(object.id) or 0)
    local npc_type = non_empty_string(props.npc_type) or ""
    local dialogue_id = non_empty_string(props.dialogue_id)
    local dialogue_text = non_empty_string(props.dialogue_text)
    if not dialogue_id and dialogue_text then
        dialogue_id = npc_id .. "_dialogue"
    end
    local world_x, world_y, pos = world_point(object, room_id)

    msg.post("main:/main_go#script", hash("spawn_npc"), {
        id = object.id,
        npc_id = npc_id,
        position = pos,
        room_id = room_id,
        properties = {
            npc_type = npc_type,
            npc_name = props.npc_name,
            npc_sprite = props.npc_sprite,
            dialogue_id = dialogue_id,
            dialogue_text = props.dialogue_text,
            facing = props.facing,
            interaction_range = props.interaction_range,
            despawn_flag = props.despawn_flag,
        },
    })

    log_spawn("NPC", npc_id, world_x, world_y, string.format("(type: %s)", npc_type))
    return object.id
end

--- Handle fast travel station object
-- Tiled properties:
--   station_id: string (unique fast travel point ID)
--   station_name/display_name: string (display name on map)
--   description: string (station description for UI)
--   icon: string (map icon type)
--   requires_unlock: bool (must be activated first)
--   unlock_cost: number (currency to unlock, 0 = free)
--   show_on_map: bool (whether to show on world map)
--   facing: int (player facing direction after teleport)

function handlers.light_source(object, room_id)
    local props = get_props(object)
    local light_id = make_id(props, "light_id", "light", object, room_id)

    local ox, oy = get_room_world_offset(room_id)
    local raw_w = tonumber(object.width) or 0
    local raw_h = tonumber(object.height) or 0
    local is_point_light = object.point or object.shape == "point" or (raw_w <= 0 and raw_h <= 0)

    local world_x = object.x + ox
    local world_y = object.y + oy
    if not is_point_light and raw_w > 0 and raw_h > 0 then
        world_x = world_x + (raw_w * 0.5)
        world_y = world_y + (raw_h * 0.5)
    end
    local pos = vmath.vector3(world_x, world_y, 0)

    local configured_radius = tonumber(OP.get(props, "radius")) or 200
    local derived_radius = configured_radius
    if not is_point_light then
        local _, _, rect_w, rect_h = rect_scale_from_size(object.width, object.height, 16, 16, 32, 32)
        derived_radius = math.max(configured_radius, math.max(rect_w or 0, rect_h or 0) * 0.5)
    end

    local instance = spawn_factory("light_source_factory", pos, {
        light_id = light_id,
        radius = derived_radius,
        intensity = OP.get(props, "intensity", 1.0),
        enabled = to_bool(props.enabled, true),
        track_position = to_bool(props.track_position, false),
        room_id = room_id,
    }, 1, "light source")

    if not instance then
        return nil
    end

    if not is_point_light then
        apply_scale(instance, object.width, object.height, 16, 16, 32, 32)
    end

    log_spawn("light source", light_id, world_x, world_y)
    return instance
end

