--- Handle secret area object (for tracking/minimap)
-- Tiled properties:
--   secret_type: string (type from secret_types.lua: "illusory_wall", "hidden_room", "destructible")
--   reveals_on: string ("touch", "attack", "ability", "interact")
--   required_ability: string (ability needed to reveal)
--   hide_tiles: bool (hide underlying tilemap tiles when revealed)
--   notification: bool (show notification when discovered)
--   notification_text: string (custom notification text)
--   map_reveal: bool (reveal area on map when discovered)

function handlers.player_spawn(object, room_id)
    local props = get_props(object)
    props.spawn_type = props.spawn_type or "player"
    if props.is_default == nil and props.default ~= nil then
        props.is_default = props.default
    end
    if props.spawn_id ~= nil and props.registration_id == nil then
        props.registration_id = props.spawn_id
    end
    object.properties = props
    return M.handlers.spawn_point(object, room_id)
end

