    local instance = spawn_factory("health_station_factory", pos, {
        station_id = station_id,
        range = tonumber(props.range) or 96,
        heal_amount = tonumber(props.heal_amount) or 0,
        heal_percent = tonumber(props.heal_percent) or 0,
        uses = tonumber(props.uses) or 0,
