--   lore_id: string (unique identifier, also key in localization)
--   prompt_text: string (interaction label override)
--   title: string (display title)
--   text: string (the lore text, or localization key)
--   content: string (alias for text)
--   category: string (for journal organization: "world", "characters", "history")
--   lore_type: string (alias for category)
--   auto_pickup: bool (if true, collect on contact)
--   destroyable: bool (if true, object disappears after reading)
--   trigger_once: bool (if true, only shows popup once)
--   unlock_flag: string (flag to set when read)
--   requires_flag: string (flag required to read)
--   sound_id: string (sound when collected/read)
--   particle_id: string (particle effect when collected)

function handlers.checkpoint(object, room_id)
    local props = get_props(object)
    local checkpoint_id = make_id(props, "checkpoint_id", "checkpoint", object, room_id)
    local _, _, pos = world_point(object, room_id)

    local instance = spawn_factory("checkpoint_factory", pos, {
        checkpoint_id = checkpoint_id,
        respawn_facing = props.respawn_facing or 1,
        trigger_once = to_bool(props.trigger_once, false),
        sound_id = optional_id(props.sound_id) or "save_point",
        particle_id = props.particle_id or "checkpoint_glow",
        room_id = room_id,
        requires_flag = props.requires_flag or "",
        set_flag = props.set_flag or "",
    }, 1, "checkpoint")

    if not instance then return nil end

    apply_scale(instance, object.width, object.height, 32, 32, 64, 64)

    send_tiled_props(instance, props)

    log_spawn("checkpoint", checkpoint_id, pos.x, pos.y)
    return instance
end

--- Handle wall jump surface (specific area where wall jump is allowed)
-- Tiled properties:
--   surface_id: string (unique identifier)
--   allow_slide: bool (enable wall sliding on this surface)
--   allow_jump: bool (enable wall jumping on this surface)
--   allow_climb: bool (enable wall climbing on this surface)
--   slide_speed: number (fall speed multiplier or speed override)
--   jump_force_x: number (horizontal wall jump force)
--   jump_force_y: number (vertical wall jump force)
--   facing: number (1 = right-facing wall, -1 = left-facing wall)
--   direction: string (alias: "left"/"right"/"both")
--   require_ability: string (ability required to use, e.g. "wall_jump")
--   surface_type: string (visual/audio type)

-- Handler aliases for authored object type synonyms.
handlers.player_start = handlers.player_spawn
handlers.respawn_point = handlers.player_spawn
handlers.healing_fountain = handlers.health_station
handlers.mana_fountain = handlers.energy_station
handlers.cartographer = handlers.map_station

    return handlers
end
